<div class="booking-container">
    <h1>预约您的保洁服务</h1>
    <form id="bookingForm" onsubmit="return handleForm(event)">
        <div class="form-row">
            <div class="form-group">
                <label for="name">姓名 *</label>
                <input type="text" id="name" name="name" placeholder="请输入您的姓名" required>
            </div>
            <div class="form-group">
                <label for="phone">联系电话 *</label>
                <input type="tel" id="phone" name="phone" placeholder="请输入手机号" required>
            </div>
        </div>

        <div class="form-group">
            <label for="address">服务地址 *</label>
            <input type="text" id="address" name="address" placeholder="请输入详细的家庭地址" required>
        </div>

        <div class="form-row">
            <div class="form-group">
                <label for="service">选择服务项目 *</label>
                <select id="service" name="service" required>
                    <option value="">--请选择项目--</option>
                    <option value="daily">基础日常保洁</option>
                    <option value="deep">深度保洁服务</option>
                    <option value="post-reno">开荒/入驻保洁</option>
                </select>
            </div>
            <div class="form-group">
                <label for="date">预约日期 *</label>
                <input type="date" id="date" name="date" required>
            </div>
        </div>

        <div class="form-group">
            <label for="time">预约时间段</label>
            <select id="time" name="time">
                <option value="morning">上午 (08:00 - 12:00)</option>
                <option value="afternoon">下午 (13:00 - 18:00)</option>
                <option value="evening">晚上 (18:00 - 21:00)</option>
            </select>
        </div>

        <div class="form-group">
            <label for="notes">特殊要求/备注</label>
            <textarea id="notes" name="notes" rows="4" placeholder="例如：重点清洁厨房油烟机，或者家中宠物需要照顾等..."></textarea>
        </div>

        <button type="submit" class="submit-btn">提交预约申请</button>
    </form>
    <div class="contact-info">
        提交后，我们的客户经理将在 30 分钟内与您联系确认具体时间。
    </div>
</div>

